  <link rel="stylesheet" href="/assets/styles.css">
  <script type="module" src="/assets/app.js"></script>
</head>
<body>
  <canvas class="skyesol-living-field living-field" aria-hidden="true"></canvas>
  <div class="scroll-progress" aria-hidden="true"></div>

  <header class="factory-top">
    <a class="brand" href="/" aria-label="Client App Factory home">
      <span class="wordmark">Sovereign Client App Factory</span>
    </a>
    <nav class="top-actions" aria-label="Factory actions">
      <span class="backend-status" data-backend-status>Factory API checking</span>
      <button class="btn ghost" type="button" data-load-empire>Load Empire Record</button>
      <button class="btn primary" type="button" data-run-factory>Run Factory Pass</button>
      <button class="btn" type="button" data-export-record>Export Record</button>
    </nav>
  </header>

  <main class="factory-shell">
    <aside class="room-rail" aria-label="Factory rooms">
      <button class="room-tab active" type="button" data-room-target="overview">Overview</button>
      <button class="room-tab" type="button" data-room-target="intake">Client Intake</button>
      <button class="room-tab" type="button" data-room-target="scanner">Source Scanner</button>
      <button class="room-tab" type="button" data-room-target="assets">Asset Vault</button>
      <button class="room-tab" type="button" data-room-target="design">Design Lab</button>
      <button class="room-tab" type="button" data-room-target="builder">App Builder</button>
      <button class="room-tab" type="button" data-room-target="workspace">AI Workspace</button>
      <button class="room-tab" type="button" data-room-target="skyepay">SkyePay</button>
      <button class="room-tab" type="button" data-room-target="proof">Proof Room</button>
      <button class="room-tab" type="button" data-room-target="deploy">Deployment Console</button>
      <button class="room-tab" type="button" data-room-target="wiring">Repo Wiring</button>
    </aside>

    <section class="workspace">
      <section class="hero-panel room active" data-room="overview">
        <div class="hero-copy">
          <p class="eyebrow">Operating app for every client app</p>
          <h1><span class="text-shimmer premium-text-effect text-effect-shimmer neon-gradient-text">Client packets become deployable app systems.</span></h1>
          <p class="lead">This factory turns intake, folders, assets, MCP recipes, proof, workspace setup, SkyePay continuation, and deployment records into one repeatable operating surface.</p>
          <div class="hero-actions">
            <button class="btn primary" type="button" data-load-empire>Seed with Empire Pallets</button>
            <a class="btn" href="#proof-room" data-room-link="proof">Open Proof Room</a>
            <a class="btn ghost" href="client-apps/empire-pallets/index.html">Open Empire App</a>
          </div>
        </div>
        <div class="surface-card">
          <div class="surface-header">
            <strong data-client-name>Empire Pallets</strong>
            <span data-client-status>preview-ready</span>
          </div>
          <div class="state-grid" data-state-grid></div>
        </div>
        <div class="ledger-strip panel">
          <div>
            <p class="eyebrow">Factory ledger</p>
            <h3>Backend events written by the local service.</h3>
          </div>
          <div class="ledger-list" data-ledger-list></div>
        </div>
      </section>

      <section class="room" data-room="intake">
        <div class="section-head">
          <p class="eyebrow">Client Intake</p>
          <h2>Source-of-truth record before generation.</h2>
        </div>
        <form class="factory-form" data-intake-form>
          <label>Client name<input name="displayName" required></label>
          <label>Industry<input name="industry"></label>
          <label>Primary contact<input name="primaryContact"></label>
          <label>Phone<input name="phone"></label>
          <label>Email<input name="email" type="email"></label>
          <label>Live URL<input name="liveUrl" type="url"></label>
          <label class="wide">Services<textarea name="services"></textarea></label>
          <label class="wide">Special notes<textarea name="notes"></textarea></label>
          <button class="btn primary" type="submit">Save Intake Record</button>
        </form>
      </section>

      <section class="room" data-room="scanner">
        <div class="section-head">
          <p class="eyebrow">Source Scanner</p>
          <h2>Scan folders, media, routes, and path risk.</h2>
        </div>
        <div class="split">
          <div class="panel">
            <h3>Empire seed scan</h3>
            <p>The Node scanner inventories the Empire packet, upgraded app, media, app routes, PWA files, and source preservation checks.</p>
            <button class="btn primary" type="button" data-load-scan>Load Latest Scan Report</button>
          </div>
          <pre class="console" data-scan-output>Run scripts/factory-scan.mjs or load the bundled report.</pre>
        </div>
      </section>

      <section class="room" data-room="assets">
        <div class="section-head">
          <p class="eyebrow">Asset Vault</p>
          <h2>Every logo, media file, zip, and provenance note stays attached.</h2>
        </div>
        <form class="asset-upload panel" data-asset-upload>
          <label>Attach asset<input name="assetFile" type="file"></label>
          <label>Provenance note<input name="provenance" aria-label="Asset provenance note"></label>
          <button class="btn primary" type="submit">Catalog Asset</button>
        </form>
        <div class="asset-grid" data-asset-grid></div>
      </section>

      <section class="room" data-room="design">
        <div class="section-head">
          <p class="eyebrow">MCP Design Lab</p>
          <h2>Design is selected as DNA, not reused as one style.</h2>
        </div>
        <div class="engine-grid" data-design-engines></div>
      </section>

      <section class="room" data-room="builder">
        <div class="section-head">
          <p class="eyebrow">App Builder</p>
          <h2>Route map, PWA shell, QR lane, preview lane, quote lane.</h2>
        </div>
        <div class="route-map" data-route-map></div>
        <div class="panel">
          <h3>Generated path manifest</h3>
          <pre class="console" data-path-manifest></pre>
        </div>
      </section>

      <section class="room" data-room="workspace">
        <div class="section-head">
          <p class="eyebrow">AI Workspace</p>
          <h2>Tester access, scans, commands, and continuation status.</h2>
        </div>
        <div class="metric-grid" data-workspace-grid></div>
      </section>

      <section class="room" data-room="skyepay">
        <div class="section-head">
          <p class="eyebrow">SkyePay</p>
          <h2>Preview-to-paid continuation lane.</h2>
        </div>
        <div class="split">
          <div class="panel">
            <h3>Payment lane</h3>
            <p>Free preview first. Owner approval, subscription, vault access, discount, invoice, and cancellation state are tracked before live payment connection.</p>
            <a class="btn primary" href="../SkyeGateFS27/skyepay.html?client=empire-pallets">Open SkyePay Client Lane</a>
          </div>
          <div class="panel">
            <h3>Continuation offer</h3>
            <ul class="check-list">
              <li>7-day tester workspace</li>
              <li>7 scans included</li>
              <li>25 workspace commands included</li>
              <li>Six-month continuation discount ready</li>
            </ul>
          </div>
        </div>
      </section>

      <section class="room" id="proof-room" data-room="proof">
        <div class="section-head">
          <p class="eyebrow">Proof Room</p>
          <h2>Browser proof, scanner proof, MCP receipts, and client-ready summaries.</h2>
        </div>
        <div class="proof-reel panel">
          <div>
            <h3>Factory workflow recording</h3>
            <p>The proof reel is created by Playwright while the browser runs the factory flow: scanner, factory pass, proof room, route map, and intake save.</p>
          </div>
          <video data-proof-video src="assets/proof/client-app-factory-workflow.webm" poster="assets/proof/client-app-factory-workflow-poster.png" controls muted playsinline preload="none"></video>
        </div>
        <div class="screenshot-stage panel" data-surface-screenshot-stage>
          <div>
            <h3>Actual surface screenshots</h3>
            <p>Desktop and mobile captures are written by the browser proof run from this exact served factory surface.</p>
          </div>
          <div class="screenshot-grid">
            <figure>
              <img data-surface-screenshot src="assets/proof/client-app-factory-desktop.png" alt="Desktop screenshot of the Client App Factory operating surface" loading="lazy" decoding="async">
              <figcaption>1440 by 1000 browser surface</figcaption>
            </figure>
            <figure>
              <img data-surface-screenshot src="assets/proof/client-app-factory-mobile.png" alt="Mobile screenshot of the Client App Factory operating surface" loading="lazy" decoding="async">
              <figcaption>390 by 844 browser surface</figcaption>
            </figure>
          </div>
        </div>
        <div class="proof-grid" data-proof-grid></div>
        <div class="panel">
          <h3>Persisted proof ledger</h3>
          <div class="ledger-list tall" data-proof-ledger></div>
        </div>
      </section>

      <section class="room" data-room="deploy">
        <div class="section-head">
          <p class="eyebrow">Deployment Console</p>
          <h2>Netlify, Cloudflare, QR regeneration, rollback, live verification.</h2>
        </div>
        <div class="split">
          <div class="panel">
            <h3>Publish target</h3>
            <pre class="console" data-deploy-console></pre>
          </div>
          <div class="panel">
            <h3>Completion gate</h3>
            <div class="gate-list" data-gate-list></div>
          </div>
        </div>
      </section>

      <section class="room" data-room="wiring">
        <div class="section-head">
          <p class="eyebrow">Repo Platform Wiring</p>
          <h2>Where the app came from, where it deploys, and which integrations are ready.</h2>
        </div>
        <div class="wiring-grid" data-wiring-grid></div>
      </section>
    </section>
  </main>

  <template id="download-template"></template>
</body>
</html>


CSS SOURCE

:root {
  color-scheme: dark;
  --ink: #f7f2e7;
  --muted: #b9b0a0;
  --quiet: #746b5d;
  --line: rgba(247, 242, 231, 0.14);
  --line-strong: rgba(247, 242, 231, 0.28);
  --bg: #080907;
  --panel: rgba(19, 21, 18, 0.86);
  --panel-strong: rgba(31, 34, 29, 0.94);
  --gold: #e0b35a;
  --green: #6dc489;
  --blue: #80bdd5;
  --clay: #d97951;
  --danger: #e36c69;
  --shadow: 0 22px 70px rgba(0, 0, 0, 0.36);
  --radius: 8px;
  --font: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  min-height: 100%;
  background: var(--bg);
  scroll-behavior: smooth;
}

body {
  min-height: 100%;
  margin: 0;
  overflow-x: hidden;
  color: var(--ink);
  background:
    linear-gradient(90deg, rgba(224, 179, 90, 0.08) 1px, transparent 1px),
    linear-gradient(180deg, rgba(128, 189, 213, 0.06) 1px, transparent 1px),
    radial-gradient(circle at 20% 0%, rgba(109, 196, 137, 0.11), transparent 34rem),
    linear-gradient(145deg, #080907 0%, #10110d 52%, #17100c 100%);
  background-size: 56px 56px, 56px 56px, auto, auto;
  font-family: var(--font);
}

body::before {
  position: fixed;
  inset: 0;
  z-index: -3;
  pointer-events: none;
  content: "";
  background:
    linear-gradient(120deg, rgba(217, 121, 81, 0.12), transparent 34%),
    linear-gradient(240deg, rgba(128, 189, 213, 0.13), transparent 38%),
    rgba(8, 9, 7, 0.5);
  mix-blend-mode: screen;
}

* {
  scrollbar-color: var(--gold) rgba(247, 242, 231, 0.1);
}

::-webkit-scrollbar {
  width: 16px;
  height: 16px;
}

::-webkit-scrollbar-track {
  border: 1px solid rgba(224, 179, 90, 0.22);
  background: linear-gradient(180deg, rgba(247, 242, 231, 0.1), rgba(128, 189, 213, 0.06));
  box-shadow: inset 0 0 18px rgba(8, 9, 7, 0.88);
}

::-webkit-scrollbar-thumb {
  border: 3px solid rgba(8, 9, 7, 0.82);
  border-radius: 999px;
  background: linear-gradient(180deg, #f8cb5e, #27f2ff);
  box-shadow: 0 0 18px rgba(39, 242, 255, 0.52), inset 0 0 10px rgba(248, 203, 94, 0.38);
}

button,
input,
textarea {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a {
  color: inherit;
  text-decoration: none;
}

.living-field {
  position: fixed;
  inset: 0;
  z-index: -2;
  width: 100%;
  height: 100%;
  pointer-events: none;
  opacity: 0.72;
}

.scroll-progress {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 30;
  width: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--gold), var(--green), var(--blue));
  box-shadow: 0 0 22px rgba(224, 179, 90, 0.6);
}

.factory-top {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem clamp(1rem, 3vw, 2rem);
  border-bottom: 1px solid var(--line);
  background: rgba(8, 9, 7, 0.82);
  backdrop-filter: blur(20px);
}

.brand {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  gap: 0.75rem;
  font-weight: 800;
}

.wordmark {
  display: inline-block;
  max-width: 100%;
  color: var(--ink);
  font-size: clamp(1.02rem, 2vw, 1.28rem);
  line-height: 1.1;
  overflow-wrap: anywhere;
}

.top-actions,
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.65rem;
}

.backend-status {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 0.48rem 0.68rem;
  border: 1px solid rgba(128, 189, 213, 0.28);
  border-radius: var(--radius);
  color: var(--blue);
  background: rgba(128, 189, 213, 0.08);
  font-size: 0.82rem;
  font-weight: 800;
}

.backend-status.ok {
  color: var(--green);
  border-color: rgba(109, 196, 137, 0.38);
  background: rgba(109, 196, 137, 0.09);
}

.backend-status.warn {
  color: var(--clay);
  border-color: rgba(217, 121, 81, 0.38);
  background: rgba(217, 121, 81, 0.09);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 42px;
  padding: 0.72rem 1rem;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  color: var(--ink);
  background: rgba(247, 242, 231, 0.07);
  box-shadow: inset 0 1px rgba(255, 255, 255, 0.06);
  cursor: pointer;
  transition: transform 180ms ease, border-color 180ms ease, background 180ms ease;
}

.btn:hover,
.btn:focus-visible {
  transform: translateY(-1px);
  border-color: rgba(224, 179, 90, 0.65);
  background: rgba(224, 179, 90, 0.13);
  outline: none;
}

.btn.primary {
  border-color: rgba(224, 179, 90, 0.72);
  color: #130f08;
  background: linear-gradient(135deg, var(--gold), #f2d78c);
}

.btn.ghost {
  background: rgba(109, 196, 137, 0.09);
  border-color: rgba(109, 196, 137, 0.3);
}

.factory-shell {
  display: grid;
  grid-template-columns: minmax(220px, 260px) minmax(0, 1fr);
  gap: clamp(1rem, 2vw, 1.5rem);
  width: min(1640px, 100%);
  min-height: calc(100vh - 76px);
  margin: 0 auto;
  padding: clamp(1rem, 2vw, 1.5rem);
}

.room-rail {
  position: sticky;
  top: 88px;
  display: flex;
  height: max-content;
  max-height: calc(100vh - 110px);
  flex-direction: column;
  gap: 0.45rem;
  padding: 0.6rem;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(13, 15, 12, 0.82);
  box-shadow: var(--shadow);
}

.room-tab {
  width: 100%;
  padding: 0.8rem 0.85rem;
  border: 1px solid transparent;
  border-radius: 7px;
  color: var(--muted);
  text-align: left;
  background: transparent;
  cursor: pointer;
}

.room-tab:hover,
.room-tab:focus-visible,
.room-tab.active {
  color: var(--ink);
  border-color: rgba(224, 179, 90, 0.32);
  background: linear-gradient(90deg, rgba(224, 179, 90, 0.14), rgba(128, 189, 213, 0.06));
  outline: none;
}

.workspace {
  min-width: 0;
}

.room {
  display: none;
  min-width: 0;
  animation: roomIn 420ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.room.active {
  display: block;
}

@keyframes roomIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-panel {
  min-height: min(820px, calc(100vh - 110px));
  padding: clamp(1.2rem, 3vw, 2rem);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(120deg, rgba(19, 21, 18, 0.86), rgba(8, 9, 7, 0.66)),
    linear-gradient(90deg, rgba(224, 179, 90, 0.08), rgba(128, 189, 213, 0.07));
  box-shadow: var(--shadow);
}

.hero-panel.active {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(320px, 0.72fr);
  align-items: stretch;
  gap: clamp(1rem, 3vw, 2rem);
}

.hero-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1rem;
  min-width: 0;
}

.eyebrow {
  margin: 0;
  color: var(--gold);
  font-size: 0.85rem;
  font-weight: 800;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  max-width: 950px;
  margin-bottom: 0;
  font-size: clamp(3rem, 7vw, 6.9rem);
  line-height: 0.92;
  overflow-wrap: anywhere;
}

h2 {
  max-width: 920px;
  margin-bottom: 0;
  font-size: clamp(2rem, 4.5vw, 4.75rem);
  line-height: 0.96;
  overflow-wrap: anywhere;
}

h3 {
  margin-bottom: 0.6rem;
  font-size: clamp(1.05rem, 2vw, 1.5rem);
}

.lead {
  max-width: 760px;
  margin-bottom: 0.45rem;
  color: var(--muted);
  font-size: clamp(1.05rem, 2vw, 1.35rem);
  line-height: 1.58;
}

.text-shimmer {
  display: inline-block;
  max-width: 100%;
  overflow-wrap: anywhere;
  background: linear-gradient(100deg, #fff8e8 0%, var(--gold) 32%, var(--green) 58%, var(--blue) 84%, #fff8e8 100%);
  background-size: 260% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: textSweep 8s ease-in-out infinite;
}

.premium-text-effect,
.text-effect-shimmer,
.neon-gradient-text {
  text-shadow: 0 0 24px rgba(224, 179, 90, 0.18), 0 0 40px rgba(128, 189, 213, 0.1);
}

@keyframes textSweep {
  0%,
  100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

.surface-card,
.panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel);
  box-shadow: var(--shadow);
}

.surface-card {
  display: flex;
  min-height: 100%;
  flex-direction: column;
  padding: 1rem;
}

.ledger-strip {
  grid-column: 1 / -1;
}

.surface-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 0.9rem;
  border-bottom: 1px solid var(--line);
}

.surface-header span {
  padding: 0.36rem 0.55rem;
  border: 1px solid rgba(109, 196, 137, 0.32);
  border-radius: 999px;
  color: var(--green);
  background: rgba(109, 196, 137, 0.08);
  font-size: 0.85rem;
  white-space: nowrap;
}

.state-grid,
.asset-grid,
.engine-grid,
.route-map,
.metric-grid,
.proof-grid,
.wiring-grid,
.gate-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 210px), 1fr));
  gap: 0.85rem;
  min-width: 0;
}

.state-grid {
  align-content: start;
  padding-top: 1rem;
}

.state-item,
.asset-item,
.engine-item,
.route-item,
.metric,
.proof-item,
.wire-item,
.gate-item {
  min-width: 0;
  padding: 0.95rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(247, 242, 231, 0.055);
}

.state-item {
  position: relative;
  overflow: hidden;
}

.state-item::before {
  position: absolute;
  inset: 0 0 auto;
  height: 3px;
  content: "";
  background: var(--quiet);
}

.state-item.complete::before {
  background: linear-gradient(90deg, var(--green), var(--gold));
}

.state-item.pending::before {
  background: linear-gradient(90deg, var(--blue), var(--clay));
}

.state-item strong,
.asset-item strong,
.engine-item strong,
.route-item strong,
.metric strong,
.proof-item strong,
.wire-item strong,
.gate-item strong {
  display: block;
  margin-bottom: 0.45rem;
  overflow-wrap: anywhere;
}

.state-item span,
.asset-item span,
.engine-item span,
.route-item span,
.metric span,
.proof-item span,
.wire-item span,
.gate-item span {
  color: var(--muted);
  font-size: 0.92rem;
  line-height: 1.45;
}

.section-head {
  margin-bottom: 1.2rem;
  padding: clamp(1.1rem, 2vw, 1.45rem);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: linear-gradient(135deg, rgba(19, 21, 18, 0.9), rgba(31, 34, 29, 0.78));
  box-shadow: var(--shadow);
}

.factory-form {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.85rem;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel);
  box-shadow: var(--shadow);
}

.asset-upload {
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1fr) auto;
  align-items: end;
  gap: 0.85rem;
  margin-bottom: 1rem;
}

label {
  display: grid;
  min-width: 0;
  gap: 0.45rem;
  color: var(--muted);
  font-size: 0.92rem;
}

