  let raf = 0;
  const pointer = { x: 0, y: 0, tx: 0, ty: 0 };
  const colors = ["rgba(240,195,91,", "rgba(107,191,89,", "rgba(158,182,186,"];

  const resize = () => {
    const ratio = Math.min(devicePixelRatio || 1, 1.5);
