  align-items: center;
  margin-bottom: 1rem;
}

.screenshot-stage {
  margin-bottom: 1rem;
}

.screenshot-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(180px, 0.38fr);
  gap: 1rem;
  align-items: start;
}

.screenshot-grid figure {
  min-width: 0;
  margin: 0;
}

.screenshot-grid img {
  display: block;
  width: 100%;
  border: 1px solid rgba(128, 189, 213, 0.26);
  border-radius: 7px;
  background: rgba(0, 0, 0, 0.35);
}

.screenshot-grid figcaption {
  margin-top: 0.45rem;
  color: var(--muted);
  font-size: 0.84rem;
}

.proof-reel video {
  width: 100%;
  aspect-ratio: 16 / 9;
  border: 1px solid rgba(128, 189, 213, 0.26);
  border-radius: 7px;
  background: rgba(0, 0, 0, 0.42);
  display: block;
}

.asset-thumb {
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(0, 0, 0, 0.22);
}

.asset-thumb img,
.asset-thumb video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.file-tile {
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  padding: 1rem;
  color: var(--gold);
  text-align: center;
  overflow-wrap: anywhere;
  background: linear-gradient(135deg, rgba(224, 179, 90, 0.1), rgba(128, 189, 213, 0.08));
}

.status-pill {
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  padding: 0.28rem 0.5rem;
  border: 1px solid rgba(128, 189, 213, 0.3);
  border-radius: 999px;
  color: var(--blue);
  background: rgba(128, 189, 213, 0.08);
  font-size: 0.8rem;
}

.status-pill.ok {
  color: var(--green);
  border-color: rgba(109, 196, 137, 0.35);
  background: rgba(109, 196, 137, 0.08);
}

.ledger-list {
  display: grid;
  gap: 0.65rem;
  max-height: 240px;
  overflow: auto;
}

.ledger-list.tall {
  max-height: 420px;
}

.ledger-event {
  display: grid;
  grid-template-columns: minmax(120px, 0.22fr) minmax(0, 1fr) minmax(120px, 0.22fr);
  gap: 0.75rem;
  align-items: start;
  padding: 0.78rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(247, 242, 231, 0.045);
}

.ledger-event strong,
.ledger-event span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.ledger-event strong {
  color: var(--gold);
  font-size: 0.88rem;
}

.ledger-event span {
  color: var(--muted);
  font-size: 0.86rem;
  line-height: 1.45;
}

.status-pill.warn {
  color: var(--clay);
  border-color: rgba(217, 121, 81, 0.38);
  background: rgba(217, 121, 81, 0.1);
}

.route-item a,
.proof-item a,
.wire-item a {
  display: inline-flex;
  margin-top: 0.7rem;
  color: var(--gold);
  overflow-wrap: anywhere;
}

@media (max-width: 1120px) {
  .factory-shell {
    grid-template-columns: 1fr;
  }

  .room-rail {
    position: relative;
    top: auto;
    flex-direction: row;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    max-height: none;
    overflow-x: auto;
  }

  .room-tab {
    width: auto;
    flex: 0 0 auto;
    white-space: nowrap;
  }

  .hero-panel.active,
  .split,
  .proof-reel,
  .screenshot-grid,
  .asset-upload {
    grid-template-columns: 1fr;
  }

  .ledger-event {
    grid-template-columns: minmax(110px, 0.28fr) minmax(0, 1fr);
  }

  .ledger-event span:last-child {
    grid-column: 1 / -1;
  }
}

@media (max-width: 720px) {
  .factory-top {
    align-items: flex-start;
    flex-direction: column;
  }

  .top-actions,
  .hero-actions {
    width: 100%;
  }

  .btn {
    width: 100%;
  }

  .backend-status {
    width: 100%;
    justify-content: center;
  }

  h1 {
    font-size: clamp(2.35rem, 13vw, 3.55rem);
  }

  h2 {
    font-size: clamp(1.9rem, 11vw, 3.1rem);
  }

  .factory-form,
  label.wide {
    grid-template-columns: 1fr;
    grid-column: auto;
  }

  .ledger-event {
    grid-template-columns: 1fr;
  }

  .ledger-event span:last-child {
    grid-column: auto;
  }

  .hero-panel,
  .section-head,
  .panel,
  .surface-card {
    padding: 0.9rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.001ms !important;
  }
}


